--
-- Table structure for table `budget_details`
--

DROP TABLE IF EXISTS `budget_details`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `budget_details` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `master_budget_id` bigint unsigned NOT NULL,
  `category_id` bigint unsigned NOT NULL,
  `category_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `budget` decimal(15,0) NOT NULL,
  `percentage` decimal(8,2) NOT NULL DEFAULT '0.00',
  `used_amount` decimal(15,2) NOT NULL DEFAULT '0.00',
  `created_at` timestamp NOT NULL,
  `updated_at` timestamp NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `master_budget_id` (`master_budget_id`,`category_id`),
