DROP TABLE IF EXISTS `mrp_details`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `mrp_details` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `mrp_id` bigint unsigned NOT NULL,
  `product_id` bigint unsigned NOT NULL,
  `class_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'Component',
  `source_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'Buy',
  `need_all_qty` decimal(15,2) DEFAULT '0.00',
  `stock_std_qty` decimal(15,2) DEFAULT '0.00',
  `sto_qty` decimal(15,2) DEFAULT '0.00',
  `gross_qty` decimal(15,2) DEFAULT '0.00',
  `safety_stock_qty` decimal(15,2) DEFAULT '0.00',
  `current_stock` decimal(15,2) DEFAULT '0.00',
  `on_order_qty` decimal(15,2) DEFAULT '0.00',
  `qty_required` int NOT NULL,
  `net_qty` decimal(15,2) DEFAULT '0.00',
  `unit_price` decimal(15,2) DEFAULT '0.00',
  `subtotal_cost` decimal(15,2) DEFAULT '0.00',
  `bom_ref` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `supplier_id` bigint unsigned DEFAULT NULL,
  `part_no_vendor` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `part_name_vendor` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `allocation_percent` decimal(5,2) DEFAULT '0.00',
  `ord_qty` decimal(15,2) DEFAULT '0.00',
  `mrp_qty` decimal(15,2) DEFAULT '0.00',
  `amount` decimal(15,2) DEFAULT '0.00',
  `qty_released_pr` int NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `release_draft_percent` decimal(5,2) DEFAULT '100.00',
  PRIMARY KEY (`id`),
  KEY `mrp_details_mrp_id_idx` (`mrp_id`),
  CONSTRAINT `mrp_details_mrp_id_fkey` FOREIGN KEY (`mrp_id`) REFERENCES `mrps` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2664 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
