--

DROP TABLE IF EXISTS `product_suppliers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `product_suppliers` (
  `id` int NOT NULL AUTO_INCREMENT,
  `product_id` bigint unsigned NOT NULL,
  `supplier_id` bigint unsigned NOT NULL,
  `supplier_part_number` varchar(255) DEFAULT NULL,
  `purchase_price` decimal(15,2) DEFAULT '0.00',
  `sell_price` decimal(15,2) DEFAULT '0.00',
  `min_qty` decimal(15,2) DEFAULT '0.00',
  `max_qty` decimal(15,2) DEFAULT '0.00',
  `min_order` int NOT NULL DEFAULT '0',
  `is_primary` tinyint(1) DEFAULT '0',
  `allocation_percent` decimal(5,2) DEFAULT '0.00',
  `pcs_per_pack` int NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `product_name` varchar(255) DEFAULT NULL,
  `product_code` varchar(255) DEFAULT NULL,
  `product_type` varchar(100) DEFAULT NULL,
  `category_id` bigint unsigned DEFAULT NULL,
  `tax_item_code` varchar(255) DEFAULT NULL,
  `bom_code` varchar(100) DEFAULT NULL,
  `is_asset` tinyint(1) DEFAULT '0',
  `is_mandatory` tinyint(1) DEFAULT '0',
